cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv_transpose2d_fp16_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int N,
    int C_in,
    int C_out,
    int H,
    int W,
    int K,
    int stride,
    int padding,
    int groups,
    int H_out,
    int W_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int tmp   = idx / W_out;
    int h_out = tmp % H_out;
    tmp       = tmp / H_out;
    int c_out = tmp % C_out;
    int n     = tmp / C_out;

    int group = c_out / (C_out / groups);
    int c_out_in_group = c_out % (C_out / groups);
    int c_in_start = group * (C_in / groups);
    int c_in_end   = c_in_start + (C_in / groups);

    float acc = 0.0f;

    for (int c_in = c_in_start; c_in < c_in_end; ++c_in) {
        for (int kh = 0; kh < K; ++kh) {
            int out_h_base = h_out + padding - kh;
            if (out_h_base < 0) continue;
            if (out_h_base % stride != 0) continue;
            int h_in = out_h_base / stride;
            if (h_in >= H) continue;

            for (int kw = 0; kw < K; ++kw) {
                int out_w_base = w_out + padding - kw;
                if (out_w_base < 0) continue;
                if (out_w_base % stride != 0) continue;
                int w_in = out_w_base / stride;
                if (w_in >= W) continue;

                int input_idx  = ((n * C_in + c_in) * H + h_in) * W + w_in;
                int weight_idx = ((c_in * (C_out / groups) + c_out_in_group) * K + kh) * K + kw;

                __half val = input[input_idx];
                __half wgt = weight[weight_idx];
                acc += __half2float(val) * __half2float(wgt);
            }
        }
    }
    if (bias != nullptr) {
        acc += __half2float(bias[c_out]);
    }
    output[idx] = __float2half(acc);
}

void conv_transpose2d_fp16_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor output,
    int stride,
    int padding,
    int groups)
{
    const int N = input.size(0);
    const int C_in = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);
    const int C_out = weight.size(1) * groups;   // weight shape (C_in, C_out/groups, K, K)
    const int K = weight.size(2);
    const int H_out = output.size(2);
    const int W_out = output.size(3);

    const dim3 block(256);
    const dim3 grid((N * C_out * H_out * W_out + block.x - 1) / block.x);

    conv_transpose2d_fp16_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        bias.defined() ? reinterpret_cast<const __half*>(bias.data_ptr()) : nullptr,
        reinterpret_cast<__half*>(output.data_ptr()),
        N, C_in, C_out, H, W, K, stride, padding, groups, H_out, W_out);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &conv_transpose2d_fp16_forward, "ConvTranspose2d fp16 forward");
}
