                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 output_padding: int = 0,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        self.in_channels    = in_channels
        self.out_channels   = out_channels
        self.kernel_size    = kernel_size
        self.stride         = stride
        self.padding        = padding
        self.output_padding = output_padding
        self.groups         = groups
        self.bias_flag      = bias

        # weight shape: (in_channels, out_channels // groups, K, K)
        self.weight = torch.randn(in_channels,
                                  out_channels // groups,
                                  kernel_size,
                                  kernel_size,
                                  dtype=torch.float16,
                                  device='cuda')
        if bias:
            self.bias = torch.randn(out_channels,
                                    dtype=torch.float16,
                                    device='cuda')
        else:
            self.bias = torch.empty(0,
                                    dtype=torch.float16,
                                    device='cuda')

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C_in, H, W = x.shape
        K = self.kernel_size
        H_out = (H - 1) * self.stride - 2 * self.padding + K + self.output_padding
        W_out = (W - 1) * self.stride - 2 * self.padding + K + self.output_padding

        out = torch.empty(N,
                          self.out_channels,
                          H_out,
                          W_out,
                          dtype=torch.float16,
                          device='cuda')

        _ext.forward(x,
                     self.weight,
                     self.bias,
                     out,
                     self.stride,
                     self.padding,
                     self.groups)
        return out
